action.code:
uint32_t index = 0;
lfs_off_t offset = *off;

// CTZ skip-list: the level is the number of trailing zeros in the offset
// and the skip distance is 2^(level+1)
index = lfs_ctz(offset);

// Update the offset to the skip distance
*off = 1u << (index + 1);

return index;

